/**
 * The bases and host directives the declaration fixtures build on from another
 * package, the part @angular/cdk plays for Material. Installed where Node finds
 * it from them, so the check reads these declarations rather than reporting
 * them unread.
 */
import { Directive, input } from '@angular/core';

/** A base whose `title` is bound away on the host, so a subclass inherits the fix with the input. */
@Directive({ host: { '[attr.title]': 'null' } })
export abstract class FixtureCdkTitled {
  readonly title = input('');
}

/** The same base without the binding: a subclass inherits a `title` that stays on its host. */
@Directive()
export abstract class FixtureCdkHeading {
  readonly title = input('');
}

/** A mixin, the way `@angular/material/core` once exported `mixinDisabled`: the base is what a call returns. */
export function mixinDisabled<T extends abstract new (...args: never[]) => object>(base: T): T {
  return base;
}

/** Exported as a value rather than a class, so the class behind it cannot be followed. */
export const FixtureCdkDisableable = mixinDisabled(FixtureCdkHeading);

/** A tooltip's text, meant to be applied by FixtureCdkHasTooltip. */
@Directive({ selector: '[fixtureCdkTooltip]' })
export class FixtureCdkTooltip {
  readonly text = input('');
}

/**
 * Applies FixtureCdkTooltip to its own host and exposes its text as `title`
 * there, under a name only this package declares — and Angular puts both on
 * whatever host carries this one.
 */
@Directive({
  selector: '[fixtureCdkHasTooltip]',
  hostDirectives: [{ directive: FixtureCdkTooltip, inputs: ['text: title'] }],
})
export class FixtureCdkHasTooltip {}
